#!/usr/bin/env python3
import os
import ssl
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime

CERT_PATH = "/app/ssl/server.crt"


def main():
    if not os.path.isfile(CERT_PATH):
        raise SystemExit(f"Certificate not found: {CERT_PATH}")

    try:
        cert = ssl._ssl._test_decode_cert(CERT_PATH)
    except Exception as exc:
        raise SystemExit(f"Failed to load certificate: {exc}")

    subject = dict(x[0] for x in cert.get("subject", ()))
    common_name = subject.get("commonName", "N/A")

    not_after = cert.get("notAfter")
    if not not_after:
        raise SystemExit("Certificate has no expiration date")

    expires = parsedate_to_datetime(not_after)
    if expires.tzinfo is None:
        expires = expires.replace(tzinfo=timezone.utc)
    expiration_date = expires.strftime("%Y-%m-%d")

    days_left = (expires - datetime.now(timezone.utc)).days
    if days_left < 0:
        raise SystemExit("Certificate has expired")

    print(f"Common Name: {common_name}")
    print(f"Expiration Date: {expiration_date}")
    print("Certificate verification successful")


if __name__ == "__main__":
    main()
